"use client"

import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox"
import { Icon } from "@iconify/react"

import { cn } from "@/lib/utils"

// Control Room Checkbox: square acknowledge toggle.
// Unchecked: recessed dark well. Checked: the same signal-green plate as the
// primary Button (rim + inner highlight + green glow, scaled down).

// Base UI className can be a state function; the wrapper feeds it to cn(), so
// narrow it to a plain string.
type WithClassName<P> = Omit<P, "className"> & { className?: string }

function Checkbox({
  className,
  ...props
}: WithClassName<CheckboxPrimitive.Root.Props>) {
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      className={cn(
        "peer inline-flex items-center justify-center size-4 shrink-0 rounded-xs",
        "border border-border bg-input",
        "[box-shadow:var(--shadow-inset)]",
        "transition-all duration-fast",
        "hover:border-ring/50",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/60 focus-visible:ring-offset-2 focus-visible:ring-offset-background",
        "disabled:cursor-not-allowed disabled:opacity-40",
        "data-checked:border-transparent data-checked:bg-primary data-checked:text-primary-foreground",
        "data-checked:[box-shadow:var(--shadow-control)]",
        className
      )}
      {...props}
    >
      <CheckboxPrimitive.Indicator
        data-slot="checkbox-indicator"
        className={cn("flex items-center justify-center text-current")}
      >
        <Icon icon="tabler:check" className="size-full size-3" />
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  )
}
Checkbox.displayName = "Checkbox"

export { Checkbox }
